"""MetaDiT-S on the same 10 held-out test spectra, on Kaggle GPU.

Protocol is identical to _phase3_models.py: 500 diffusion steps, cfg_scale 4.0,
torch.manual_seed(0), then metric.restore_structure() -> 3-channel 64x64
geometry. The 10 spectra are embedded below (base64 NPZ) so the only external
input is the released metadit-small.bin, which is attached as a private
dataset. This kernel does NOT score anything: it returns the geometries, and
the scoring is done locally with the same frozen surrogate the JEPA run used.
"""

import base64
import io
import json
import subprocess
import sys
import time
from pathlib import Path

import numpy as np

B64 = ""
REPO_URL = "https://github.com/tegga8/metasurface-jepa.git"
WORK = Path("/kaggle/working")
REPO = WORK / "repo"


def sh(argv, cwd=None):
    print("$", " ".join(map(str, argv)), flush=True)
    subprocess.run([str(a) for a in argv], cwd=cwd, check=True)


def main():
    import torch
    print(f"torch {torch.__version__} cuda={torch.cuda.is_available()}",
          flush=True)
    device = "cuda" if torch.cuda.is_available() else "cpu"
    if device != "cuda":
        raise SystemExit("no GPU - this kernel exists to avoid the 152-min CPU loop")

    if not REPO.exists():
        sh(["git", "clone", "--depth", "1", REPO_URL, str(REPO)])
    sys.path.insert(0, str(REPO / "external" / "metadit"))

    from model.dit import DIT_MODEL
    from diffusion import create_diffusion
    from metric import restore_structure

    wpath = next(Path("/kaggle/input").rglob("metadit-small.bin"), None)
    if wpath is None:
        raise SystemExit("metadit-small.bin not found under /kaggle/input")
    print(f"weights: {wpath}", flush=True)

    z = np.load(io.BytesIO(base64.b64decode(B64)))
    spec = torch.from_numpy(np.stack([z["real"], z["imag"]], axis=1)
                            .astype(np.float32))
    print(f"spectra: {tuple(spec.shape)} indices={z['idx'].tolist()}",
          flush=True)

    diffusion = create_diffusion("500", learn_sigma=False)
    md = DIT_MODEL["metadit_s"](diffusion=diffusion, condition_channel=301)
    md.load_state_dict(torch.load(wpath, map_location="cpu"), strict=True)
    md = md.to(device).eval()

    class _Shim(torch.nn.Module):
        def __init__(self, m):
            super().__init__()
            self.m = m

        def forward(self, x, t, **kw):
            return self.m.forward_with_cfg(x, t, **kw)

    shim = _Shim(md).to(device).eval()
    b = spec.shape[0]
    torch.manual_seed(0)
    zz = torch.randn(b, 3, 32, 32, device=device)
    zz = torch.cat([zz, zz], 0)
    c = torch.cat([spec.to(device),
                   torch.ones_like(spec).to(device) * 0.5], 0)
    t0 = time.time()
    with torch.no_grad():
        sm = diffusion.p_sample_loop(
            shim, zz.shape, zz, clip_denoised=False,
            model_kwargs=dict(y=c, cfg_scale=4.0), progress=True,
            device=device)
    print(f"sampling wall time: {time.time() - t0:.1f}s", flush=True)
    sm, _ = sm.chunk(2, dim=0)
    geoms = np.stack([
        restore_structure(sm[j].detach().cpu().clone()).numpy()
        for j in range(b)])
    np.savez_compressed(WORK / "metadit_test10_geoms.npz",
                        geoms=geoms, idx=z["idx"], occ=z["occ"],
                        real=z["real"], imag=z["imag"])
    meta = dict(n=int(b), indices=z["idx"].tolist(), cfg_scale=4.0,
                steps=500, seed=0, geoms_shape=list(geoms.shape),
                occupancy_fraction=[float((geoms[k, 0] != 0).mean())
                                    for k in range(b)])
    (WORK / "meta.json").write_text(json.dumps(meta, indent=2))
    print("META", json.dumps(meta), flush=True)
    print("KERNEL DONE", flush=True)


if __name__ == "__main__":
    main()
